    name: { de: "Bjelasica Urwaldreste", hu: "Bjelasica őserdő-maradványok", ro: "Resturi de pădure virgină Bjelasica", en: "Bjelasica Virgin Forest Remnants" },
    coords: [19.5, 42.8333],
